// === Tab: mySketch ===
flip = -1; // set flip = 1 before saving an image or thumbnail, then set flip = -1
const step = 0.2;
let t = 0;
const size = 40;
let lapse = 0;    // mouse timer
let new_shader;

function setup() {
  createCanvas(1112, 834, WEBGL);
	new_shader = createShader(vert, frag);
}

function draw() {
  background(0);
	orbitControl();
	new_shader.setUniform('resolution', [width, height]);
	new_shader.setUniform('time', millis() / 1000.0);
	shader(new_shader);
  for (let j=0; j<height/size; j++) {
    for (let i=0; i<width/size; i++) {
      push();
      translate(i*size+size/2, j*size+size/2, 0);
      box(size, size, size * (sin(t * noise(i*step, j*step))+1.0));
      pop();
    }
  }
  camera(0, 0, 150, width/2, height/2, -100, 0, 0, flip);
  t += 0.05;
}

function mousePressed(){
  // prevents mouse press from registering twice
  if (millis() - lapse > 500){
    save('pix.jpg');
    lapse = millis();
  } 
} 

// === Tab: shader ===
let vert = `
attribute vec3 aPosition;
attribute vec4 aVertexColor;
attribute vec3 aNormal;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
uniform mat3 uNormalMatrix;

varying vec3 vVertexNormal;

void main(void) {
  vec4 positionVec4 = vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
	vVertexNormal = normalize(vec3(uNormalMatrix * aNormal));
}
`;


let frag = `
precision mediump float;

uniform vec4 uMaterialColor;
uniform vec2 resolution;
uniform float time;

varying vec3 vVertexNormal;

vec3 calc_color(vec2 _p) {
	float r = 0.6 + 0.4 * sin(time * 3.1375 + _p.x * 6.2487) * sin(time *  2.2738 + _p.y * 9.1263) * sin(time + dot(_p, vec2(-1.128, 3.127)));
  float g = 0.6 + 0.4 * sin(time * 2.1263 - _p.x * 1.3374) * sin(time *  0.2136 + _p.y * 2.2391) * sin(time + dot(_p, vec2(1.372, -4.184))); 
	float b = 0.6 + 0.4 * sin(time * 0.6362 + _p.x * 5.1281) * sin(time *  4.2837 - _p.y * 3.2985) * sin(time + dot(_p, vec2(-0.173, -2.302)));
	return vec3(r, g, b);
}

void main(void) {
	vec4 color = vec4(calc_color(gl_FragCoord.xy/resolution * 2.0), 1.0);
  gl_FragColor = uMaterialColor * color * vec4(0.8 + 0.2 * vVertexNormal, 1.0);
}
`

